import{_ as t,o,c as d,ag as a}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"导出到 Markdown","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/export2markdown.md","filePath":"zh/guide/export2markdown.md","lastUpdated":1783295281000}'),r={name:"zh/guide/export2markdown.md"};function c(l,e,n,i,s,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="导出到-markdown" tabindex="-1">导出到 Markdown <a class="header-anchor" href="#导出到-markdown" aria-label="Permalink to &quot;导出到 Markdown&quot;">​</a></h1><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><h3 id="方式一-右键导出" tabindex="-1">方式一：右键导出 <a class="header-anchor" href="#方式一-右键导出" aria-label="Permalink to &quot;方式一：右键导出&quot;">​</a></h3><ol><li>打开项目中包含 API 的文件，或者在 IDEA 左边项目文件区域选择文件或文件夹</li><li>鼠标右键点击文件内容或文件夹</li><li>选择 <code>ExportMarkdown</code> 导出该文件或文件夹中所有的 API</li></ol><h3 id="方式二-快捷键导出" tabindex="-1">方式二：快捷键导出 <a class="header-anchor" href="#方式二-快捷键导出" aria-label="Permalink to &quot;方式二：快捷键导出&quot;">​</a></h3><ol><li>打开项目中包含 API 的文件，或者在 IDEA 左边项目文件区域选择文件或文件夹</li><li>使用快捷键 <code>Alt + Shift + E</code> (Windows/Linux) 或 <code>Ctrl + E</code> (macOS)</li><li>选择要导出的 API，选择导出渠道 <code>Markdown</code></li><li>点击 ✔ 按钮或按回车键完成导出</li></ol><h2 id="markdown-可用设置" tabindex="-1">Markdown 可用设置 <a class="header-anchor" href="#markdown-可用设置" aria-label="Permalink to &quot;Markdown 可用设置&quot;">​</a></h2><ul><li><strong>outputDemo</strong>: 导出 Markdown 文档时，为每个 API 生成一个响应 demo</li><li><strong>outputCharset</strong>: 选择导出 Markdown 文档时使用的字符集，当导出文档出现乱码时可尝试修改此配置</li></ul><p>详见 <a href="/zh/settings/ide-setting">IDE 设置</a>。</p><h2 id="自定义模板" tabindex="-1">自定义模板 <a class="header-anchor" href="#自定义模板" aria-label="Permalink to &quot;自定义模板&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">v3.2.0 新增</p><p>自由格式的 Markdown 导出模板（支持国际化 i18n 与远程源）在 v3.2.0 中引入（#1411）。 下文所述的 Markdown 导出对话框与 <code>markdown.template*</code> 配置规则描述了完整体系。</p></div><p>触发 Markdown 导出时，EasyYapi 会打开一个对话框，允许你覆盖输出位置与渲染文档所用的模板。该对话框提供以下字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>输出目录（Output Directory）</td><td>生成 <code>.md</code> 文件的目标文件夹。留空则使用默认输出目录。</td></tr><tr><td>文件名（File Name）</td><td>输出文件名（不含扩展名）。留空则使用默认名称。</td></tr><tr><td>模板文件（Template File）</td><td>本地模板文件路径（<code>.tpl</code> 或 <code>.md.tpl</code>）。</td></tr><tr><td>模板 URL（Template URL）</td><td>提供模板的远程 <code>http(s)</code> URL。响应会被缓存 10 分钟；<strong>不</strong>跟随重定向。</td></tr><tr><td>语言（Language）</td><td>内置语言模板的下拉框（如 <code>zh-CN</code>、<code>ja</code>、<code>en</code>）。选择某个内置语言即以该语言模板渲染文档。</td></tr><tr><td>显示内联模板（Show inline template）</td><td>展开多行文本框，可直接输入模板内容。</td></tr><tr><td>复制默认模板（Copy default template）</td><td>将内置默认模板复制到内联区域，作为编辑起点。</td></tr></tbody></table><h3 id="模板解析顺序" tabindex="-1">模板解析顺序 <a class="header-anchor" href="#模板解析顺序" aria-label="Permalink to &quot;模板解析顺序&quot;">​</a></h3><p>解析器按以下层级依次查找，<strong>首个非空且成功的层级胜出</strong>。空值或失败（文件缺失、HTTP 错误、响应超限）的层级会被跳过，继续尝试下一层级。</p><ol><li>对话框中的<strong>内联模板</strong>（多行文本框）。</li><li>对话框中的<strong>本地模板文件</strong>（Template File 字段）。</li><li>对话框中的<strong>远程模板 URL</strong>（Template URL 字段）。</li><li><strong><code>markdown.template</code> 配置规则</strong>。其值会被自动检测： <ul><li><code>http(s)</code> URL 会远程拉取，</li><li>单行路径会作为本地文件读取，</li><li>其他内容（多行文本或使用双花括号占位符的内容）会作为内联模板内容处理。</li></ul></li><li><strong>基于约定的项目文件</strong> <code>&lt;project&gt;/.easyapi/markdown.tpl</code>（若存在）。团队只需提交该文件即可共享模板——无需配置 key。</li><li>由 <code>markdown.template.language</code> 配置规则<strong>或</strong>语言下拉框选中的<strong>内置语言模板</strong>（下拉框优先）。</li><li><strong>内置 <code>default.md.tpl</code></strong> 作为兜底——始终存在。</li></ol><div class="tip custom-block"><p class="custom-block-title">模板占位符使用双花括号</p><p>模板内容使用双花括号占位符来插值变量。当你在编写 Markdown <strong>文档正文</strong>（如本页）时，切勿把两个左花括号并排写出——VitePress/Vue 会将其解析为 Vue 插值，导致构建失败。在正文中请用“双花括号占位符”这一说法来指代。</p></div><h3 id="配置规则" tabindex="-1">配置规则 <a class="header-anchor" href="#配置规则" aria-label="Permalink to &quot;配置规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td><code>markdown.template</code></td><td>自动检测的模板源（远程 URL、本地文件路径或内联内容）。取代旧的 <code>markdown.template.file</code> / <code>markdown.template.url</code> / 内联 <code>markdown.template</code>，这些旧 key 已合并为这一个 key。</td></tr><tr><td><code>markdown.template.language</code></td><td>BCP-47 语言标签（如 <code>zh-CN</code>），用于选择内置语言模板。当精确标签未内置时，按 BCP-47 回退规则处理。</td></tr><tr><td><code>markdown.template.url.ttl.seconds</code></td><td>远程模板拉取的缓存 TTL。默认：<code>600</code>（10 分钟）。</td></tr><tr><td><code>markdown.template.url.max.bytes</code></td><td>远程模板拉取的最大响应大小。默认：<code>1048576</code>（1 MiB）。</td></tr></tbody></table><p>::: note 旧 key 已合并 旧版分离的 <code>markdown.template.file</code>、<code>markdown.template.url</code> 与内联形式的 <code>markdown.template</code> 已合并为单一的 <code>markdown.template</code> key（第 4 层级）。当值以 <code>http://</code> 或 <code>https://</code> 开头时被自动识别为远程 URL，否则作为本地文件路径处理，再回退为内联内容。 :::</p><h3 id="内置语言" tabindex="-1">内置语言 <a class="header-anchor" href="#内置语言" aria-label="Permalink to &quot;内置语言&quot;">​</a></h3><p>EasyYapi 为以下语言内置了模板（<code>en</code> 默认使用内置的 <code>default.md.tpl</code>）：</p><p><code>zh-CN</code>、<code>zh-TW</code>、<code>zh</code>、<code>ja</code>、<code>ko</code>、<code>es</code>、<code>fr</code>、<code>de</code>、<code>ru</code>、<code>pt-BR</code>、<code>pt</code>、<code>it</code>、<code>ar</code>、<code>hi</code>、<code>vi</code>、<code>id</code>、<code>tr</code>、<code>pl</code>、<code>uk</code>、<code>nl</code>、<code>th</code>、<code>en</code>。</p>',23)])])}const k=t(r,[["render",c]]);export{m as __pageData,k as default};
